:root {
  color-scheme:light;
  --ink:#20352f;
  --muted:#52665e;
  --accent:#1a684e;
  --paper:#f5f3eb;
  --line:#d8dfd5;
}
* {
  box-sizing:border-box;
}
body {
  margin:0;
  background:var(--paper);
  color:var(--ink);
  font:17px/1.65 system-ui,sans-serif;
}
header,main,footer {
  max-width:960px;
  margin:auto;
  padding:30px 28px;
}
header {
  padding-top:62px;
  padding-bottom:12px;
}
h1 {
  font:600 clamp(2.2rem,6vw,3.7rem)/1.12 Georgia,serif;
  letter-spacing:-.04em;
  margin:14px 0;
}
h2 {
  font-size:1.2rem;
  margin:0 0 12px;
}
.eyebrow {
  font-size:.76rem;
  letter-spacing:.15em;
  font-weight:700;
  color:var(--accent);
}
p {
  margin:8px 0 16px;
}
section {
