  border:1px solid #a8b8ae;
  border-radius:8px;
  resize:vertical;
  background:white;
}
button {
  font:600 .94rem system-ui;
  cursor:pointer;
  border:1px solid var(--accent);
  border-radius:8px;
  padding:12px 18px;
  margin-top:12px;
  background:var(--accent);
  color:white;
}
button.secondary {
  background:transparent;
  color:var(--accent);
}
button:disabled {
  opacity:.45;
  cursor:default;
}
button:focus-visible,textarea:focus-visible,summary:focus-visible {
  outline:3px solid #dc9a38;
  outline-offset:3px;
}
.actions,.toolbar {
  display:flex;
  gap:10px;
  align-items:center;
  flex-wrap:wrap;
}
.toolbar {
  justify-content:space-between;
  margin-bottom:12px;
}
.toolbar button {
  margin:0;
}
.muted,footer {
  color:var(--muted);
  font-size:.88rem;
}
.badge {
  border-radius:20px;
  background:#e8eddf;
  padding:4px 12px;
  font-size:.8rem;
  font-weight:600;
}
#status {
  margin:0 0 24px;
}
#status:not(:empty) {
  padding:14px 18px;
  border-left:4px solid var(--accent);
  background:#edf3ed;
}
#correction-form {
  border-top:1px solid var(--line);
  padding-top:20px;
}
h3 {
  font-size:1rem;
  margin:22px 0 6px;
}
li {
  margin-bottom:7px;
}
ul {
  padding-left:22px;
}
pre {
  white-space:pre-wrap;
  overflow-wrap:anywhere;
  max-height:450px;
  overflow:auto;
  padding:14px;
  border-radius:8px;
  background:#edf1ea;
  font:13px/1.5 ui-monospace,monospace;
}
details {
  margin:20px 0;
}
summary {
  cursor:pointer;
  font-weight:600;
}
[hidden] {
  display:none!important;
}
@media(max-width:600px) {
  header,main,footer {
    padding:20px;
  }
  header {
    padding-top:32px;
  }
  main>section,#clarification,#result {
    padding:18px;
  }
  .actions {
    display:block;
  }
  .actions button {
    display:block;
    width:100%;
  }
}

